#!/usr/bin/env python3
"""Trigger kernel page and general-protection faults; verify both panic terminals."""

from pathlib import Path
import os
import re
import struct
import socket
import subprocess
import sys
import tempfile
import time
import shutil

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "console"))
from serial_boot_smoke import (PROMPT, capture_record, capture_screen,
                               monitor_command, read_until, screen_lines)


def validate_panic_qr(record, memory_path, screen, vector):
    """Verify the QR generated by an actual kernel exception."""

    entry = record["panic_qr_entry"]
    scratch = record["panic_qr_scratch"]

    if entry == 0:
        raise AssertionError("Hydrogen panic QR entry missing")

    if scratch < 4096 or scratch % 4096 != 0:
        raise AssertionError(
            f"Invalid panic QR scratch address: {scratch:#x}"
        )

    # Read the actual memory populated during the panic.
    with open(memory_path, "rb") as memory:
        memory.seek(scratch)
        page = memory.read(4096)

    if len(page) != 4096:
        raise AssertionError("Incomplete QR scratch page")

    # The payload is 74 ASCII characters.
    payload = page[:74].decode("ascii")

    print(f"QR payload: {payload}")

    # Validate the AU1 payload structure.
    fields = payload.split(":")

    if len(fields) != 6 or fields[0] != "AU1":
        raise AssertionError("Invalid panic QR payload format")

    expected_vector = f"{vector:02X}"

    if fields[1] != expected_vector:
        raise AssertionError(
            f"QR vector mismatch: "
            f"expected {expected_vector}, got {fields[1]}"
        )

    for field in fields[2:]:
        if re.fullmatch(r"[0-9A-F]{16}", field) is None:
            raise AssertionError(
                f"Invalid QR diagnostic field: {field}"
            )

    # Confirm that the crash's instruction pointer appears
    # in the QR diagnostics.
    #
    # This does not assume the ordering of the four
    # diagnostic fields.
    expected_rip = f"{record['panic_rip']:016X}"

    if expected_rip not in fields[2:]:
        raise AssertionError(
            "QR payload does not contain the captured RIP"
        )

    # Extract the native Hydrogen QR matrix.
    matrix = page[192:192 + 841]

    if len(matrix) != 841:
        raise AssertionError("Incomplete QR matrix")

    if any(value not in (0, 1) for value in matrix):
        raise AssertionError("Invalid QR matrix values")

    width, height, pixels = screen

    scale = 6
    side = 37 * scale

    origin_x = width - side - 16
    origin_y = 24

    if origin_x < 512 or origin_y + side > height:
        raise AssertionError(
            "QR does not fit in the panic framebuffer"
        )

    # Compare every pixel, including the quiet zone.
    for my in range(37):
        for mx in range(37):

            black = False

            if 4 <= mx < 33 and 4 <= my < 33:
                index = (my - 4) * 29 + (mx - 4)
                black = matrix[index] == 1

            expected = (
                b"\x00\x00\x00"
                if black
                else b"\xff\xff\xff"
            ) * scale

            for py in range(scale):

                x = origin_x + mx * scale
                y = origin_y + my * scale + py

                offset = (y * width + x) * 3

                actual = pixels[
                    offset:offset + scale * 3
                ]

                if actual != expected:
                    raise AssertionError(
                        f"Panic QR framebuffer mismatch "
                        f"at module ({mx}, {my}), row {py}"
                    )

    print(f"QR vector:     0x{vector:02X}")
    print(f"QR RIP:        0x{record['panic_rip']:016X}")
    print(f"Black modules: {sum(matrix)}")
    print(f"Framebuffer:   {width} x {height}")
    print("Real panic QR framebuffer validation PASSED")


def validate_scannable_panic_qr(record, memory_path, screen_path):
    """Independently decode the real QEMU panic screenshot."""

    with open(memory_path, "rb") as memory:
        memory.seek(record["panic_qr_scratch"])
        expected = memory.read(74).decode("ascii")

    result = subprocess.run(
        ["zbarimg", "--quiet", "--raw", screen_path],
        capture_output=True,
        text=True,
        check=False,
    )

    if result.returncode != 0:
        raise AssertionError(
            "Independent QR decoding failed: "
            f"{result.stderr.strip()}"
        )

    decoded = result.stdout.strip().splitlines()

    if decoded != [expected]:
        raise AssertionError(
            f"QR decoding mismatch.\n"
            f"Expected: {expected}\n"
            f"Decoded:  {decoded}"
        )

    print("Independent QR decoding PASSED")


def run_fault(qemu, firmware, iso, command, vector):
    with tempfile.TemporaryDirectory(prefix="australis-panic-") as temporary:
        serial_path = os.path.join(temporary, "serial.sock")
        monitor_path = os.path.join(temporary, "monitor.sock")
        memory_path = os.path.join(temporary, "ram.bin")
        screen_path = os.path.join(temporary, "panic.ppm")
        arguments = [
            qemu, "-machine", "q35", "-m", "256M",
            "-drive", f"if=pflash,format=raw,readonly=on,file={firmware}",
            "-cdrom", iso, "-display", "none", "-no-reboot", "-net", "none",
            "-monitor", f"unix:{monitor_path},server=on,wait=off",
            "-serial", f"unix:{serial_path},server=on,wait=off",
            "-device", "ich9-ahci,id=ahci0",
            "-drive", f"if=none,id=sata0,format=raw,snapshot=on,file={iso}",
            "-device", "ide-hd,drive=sata0,bus=ahci0.0",
        ]
        process = subprocess.Popen(arguments, stdout=subprocess.DEVNULL,
                                   stderr=subprocess.PIPE)
        try:
            deadline = time.monotonic() + 10
            while not os.path.exists(serial_path):
                if process.poll() is not None:
                    raise RuntimeError(process.stderr.read().decode(errors="replace"))
                if time.monotonic() >= deadline:
                    raise TimeoutError("QEMU did not open its serial socket")
                time.sleep(0.05)
            with socket.socket(socket.AF_UNIX) as connection:
                connection.connect(serial_path)
                connection.settimeout(0.2)
                opening = bytearray()
                deadline = time.monotonic() + 60
                last_key = 0.0
                while PROMPT not in opening:
                    if process.poll() is not None:
                        raise RuntimeError("QEMU exited before Debug KMon prompt")
                    if time.monotonic() >= deadline:
                        raise AssertionError(f"Debug KMon prompt missing: {opening[-500:]!r}")
                    if b"[BOOT] Debug mode selected." not in opening and \
                            time.monotonic() - last_key >= 1.0:
                        monitor_command(monitor_path, "sendkey d 70")
                        last_key = time.monotonic()
                    try:
                        opening.extend(connection.recv(4096))
                    except socket.timeout:
                        pass
                connection.sendall(command + b"\r")
                report = read_until(connection,
                    b"System halted. Power cycle or reset to continue.\r\n", 20, process)

            required = [
                b"*** AUSTRALIS KERNEL PANIC ***\r\n",
                b"Fatal CPU exception; interrupts are disabled.\r\n",
                f"VECTOR  =0x{vector:016X}\r\n".encode(),
                b"ERROR   =0x0000000000000000\r\n",
                b"R15     =0x",
            ]
            for marker in required:
                if marker not in report:
                    raise AssertionError(f"serial panic report missing {marker!r}: {report[-1200:]!r}")
            for register in (b"RIP", b"RFLAGS", b"RSP", b"RAX"):
                if re.search(register + rb" + =?0x[0-9A-F]{16}", report) is None:
                    raise AssertionError(f"serial panic register missing: {register!r}")

            record = capture_record(monitor_path, memory_path)

            # The serial report completes before framebuffer rendering.
            # Wait for the panic handler to finish both outputs.
            #
            # State 1 = panic reporting in progress.
            # State 2 = panic reporting complete.
            #
            # Keep a timeout so a stuck panic handler still fails.

            deadline = time.monotonic() + 15

            while record["panic_state"] == 1:
                if time.monotonic() >= deadline:
                    raise AssertionError(
                        "Panic handler did not finish framebuffer rendering. "
                        f"Last captured state: {record}"
                    )

                time.sleep(0.25)

                record = capture_record(
                    monitor_path,
                    memory_path
                )
            if (record["exception"] != vector or record["panic_vector"] != vector or
                    record["panic_error_valid"] != 1 or record["panic_error"] != 0 or
                    (vector == 14 and record["panic_cr2"] != 0) or
                    record["panic_rip"] == 0 or
                    record["panic_rsp"] == 0 or record["panic_state"] != 2):
                raise AssertionError(f"invalid captured panic state: {record}")

            # Capture the final framebuffer once the panic handler
            # has completed and panic_state == 2.

            screen = capture_screen(
                monitor_path,
                screen_path
            )

            # Preserve the real panic screenshot for inspection.
            output = Path("build") / f"panic-qr-{vector:02X}.ppm"

            output.parent.mkdir(parents=True, exist_ok=True)

            shutil.copyfile(screen_path, output)

            print(f"Panic screenshot: {output}")

            # Verify Hydrogen's real panic QR.
            validate_panic_qr(
                record,
                memory_path,
                screen,
                vector
            )

            validate_scannable_panic_qr(
                record,
                memory_path,
                screen_path
            )

            # Preserve the original readable panic-text checks.
            lines = [
                line.rstrip()
                for line in screen_lines(screen)
            ]
            visible = "\n".join(lines)
            for marker in ("*** AUSTRALIS KERNEL PANIC ***",
                           f"VECTOR  =0x{vector:016X}",
                           "RIP     =0x", "System halted. Power cycle or reset to continue."):
                if marker not in visible:
                    raise AssertionError(f"framebuffer panic report missing {marker!r}")
            print(f"Australis kernel {command.decode()} QEMU test passed")
        finally:
            if process.poll() is None:
                process.terminate()
                try:
                    process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    process.kill()
            if process.stderr is not None:
                process.stderr.close()

def main():
    qemu, firmware, iso = sys.argv[1:4]
    run_fault(qemu, firmware, iso, b"panic", 14)
    run_fault(qemu, firmware, iso, b"panic gp", 13)


if __name__ == "__main__":
    main()
